-- Trigger [HC].[trgConfigureFacebookToken]
CREATE TRIGGER [HC].[trgConfigureFacebookToken]
   ON  HC.Kennel
   AFTER INSERT,UPDATE
AS 
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	IF (UPDATE(KennelFacebookTokenUsername) OR UPDATE(KennelFacebookToken))
	BEGIN

		declare @kennelId uniqueidentifier,
				@kennelFacebookUsername nvarchar(250),
				@kennelFacebookToken nvarchar(1000),
				@kennelFacebookTokenLastUpdated datetimeoffset(7)


		declare xCrsr CURSOR FOR
			select id,KennelFacebookTokenUsername 
			from INSERTED 

		OPEN xCrsr

		FETCH NEXT FROM xCrsr into @kennelId,@kennelFacebookUsername

		WHILE @@Fetch_status = 0
		BEGIN
			IF (@kennelFacebookUsername IS NULL)
				--SET NOCOUNT ON
				-- If the token username has been removed altogether, set the integration type to "none" and null out the other fields.
				BEGIN
					UPDATE HC.Kennel set 
						 KennelFacebookToken = null
						,KennelFacebookTokenLastUpdated = null
						--,IntegrationType = 'None' 
					FROM HC.Kennel k where k.id = @kennelId
				END
			ELSE
				BEGIN
					-- the facebook token for a user can be stored either in HC.Hasher (if they logged in to the mobile app)
					-- or in dbo.Users if they logged in using Facebook using the website. Check HC.Hasher first
					-- and then dbo.Users to see if there is a valid Facebook token for this user.
					SELECT @kennelFacebookToken = FacebookAccessToken,
						   @kennelFacebookTokenLastUpdated = FacebookAccessTokenLastUpdated 
					FROM HC.Hasher 
					--where Email = @kennelFacebookUsername OR ThirdPartyEmail = @kennelFacebookUsername
					where ThirdPartyEmail = @kennelFacebookUsername
					and FacebookAccessToken is not null

					if (@kennelFacebookToken is null)
					BEGIN
						SELECT @kennelFacebookToken = AuthToken, @kennelFacebookTokenLastUpdated = AuthTokenLastUpdated FROM dbo.Users where Username = @kennelFacebookUsername and AuthTokenType = 'FACEBOOK'
					END

					-- if we found a valid auth token, copy it to HC.Kennel
					IF (@kennelFacebookToken is not null)
						BEGIN
							UPDATE HC.Kennel set KennelFacebookToken = @kennelFacebookToken, KennelFacebookTokenLastUpdated = @kennelFacebookTokenLastUpdated 
							FROM HC.Kennel k where k.id = @kennelId
						END
					ELSE
						-- if the user was not configured with an auth token, null out the fields and set the integration type to 'none'
						BEGIN
							UPDATE HC.Kennel 
								set 
									KennelFacebookToken = null
									,KennelFacebookTokenLastUpdated = null
									--IntegrationType = 'None' 
							FROM HC.Kennel k where k.id = @kennelId
						END
				END
			

			FETCH NEXT FROM xCrsr into @kennelId,@kennelFacebookUsername
		END

		CLOSE xCrsr
		DEALLOCATE xCrsr
	END

END
GO

-- Trigger [HC].[trgForceFbRefresh]
CREATE TRIGGER [HC].[trgForceFbRefresh]
   ON  HC.Kennel
   AFTER INSERT,UPDATE
AS 
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	IF 
	     UPDATE(KennelFacebookTokenUsername) 
	  OR UPDATE(KennelFacebookToken)
	  OR UPDATE ([InboundIntegrationId])
      OR UPDATE ([IntegrationType])
      OR UPDATE ([IntegrationImportDaysInPast])
      OR UPDATE ([IntegrationImportDaysInFuture])
      OR UPDATE ([IntegrationAutoImportEvents])
      OR UPDATE ([IntegrationImportOnlyTaggedEvents])
      OR UPDATE ([IntegrationTagForImport])
      OR UPDATE ([KennelFacebookId])
      OR UPDATE ([KennelFacebookToken])
      OR UPDATE ([KennelFacebookTokenUserId])
      OR UPDATE ([KennelFacebookTokenUsername])
      OR UPDATE ([KennelFacebookTokenLastUpdated])

	BEGIN

		UPDATE k set IntegrationForceUpdatesUntil = dateadd(minute,intg.Interval * 4,getdate())
		FROM HC.Kennel k 
		INNER JOIN inserted i on k.id = i.id
		INNER JOIN HC.Integration intg on intg.IntegrationId = i.InboundIntegrationId
		
	END

END
GO

-- Trigger [HC].[trgForceIntegrationRefresh]
CREATE TRIGGER [HC].[trgForceIntegrationRefresh]
   ON  HC.Kennel
   AFTER INSERT,UPDATE
AS 
BEGIN

	SET NOCOUNT ON;

	-- If any changes are made to integration parameters, 
	-- reset the ForceUpdateUntil parameter to ensure that
	-- updates from external sources are not skipped

	IF 
	     UPDATE(KennelFacebookTokenUsername) 
	  OR UPDATE(KennelFacebookToken)
	  OR UPDATE ([InboundIntegrationId])
      OR UPDATE ([IntegrationType])
      OR UPDATE ([IntegrationImportDaysInPast])
      OR UPDATE ([IntegrationImportDaysInFuture])
      OR UPDATE ([IntegrationAutoImportEvents])
      OR UPDATE ([IntegrationImportOnlyTaggedEvents])
      OR UPDATE ([IntegrationTagForImport])
      OR UPDATE ([KennelFacebookId])
      OR UPDATE ([KennelFacebookToken])
      OR UPDATE ([KennelFacebookTokenUserId])
      OR UPDATE ([KennelFacebookTokenUsername])
      OR UPDATE ([KennelFacebookTokenLastUpdated])

	BEGIN

		UPDATE k set IntegrationForceUpdatesUntil = dateadd(minute,intg.Interval * 4,getdate())
		FROM HC.Kennel k 
		INNER JOIN inserted i on k.id = i.id
		INNER JOIN HC.Integration intg on intg.IntegrationId = i.InboundIntegrationId
		
	END

END
GO

-- Trigger [HC].[trgUpdateKennelGeolocation]
CREATE TRIGGER [HC].[trgUpdateKennelGeolocation]
   ON  HC.Kennel
   AFTER INSERT,UPDATE
AS 
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	IF UPDATE(CityId) OR UPDATE(Latitude) OR UPDATE(Longitude)
	BEGIN

		declare @kennelId uniqueidentifier,
				@cityId uniqueidentifier,
				@regionId uniqueidentifier,
				@countryId uniqueidentifier,
				@oldCityId uniqueidentifier,
				@oldRegionId uniqueidentifier,
				@oldCountryId uniqueidentifier,
				@latitude decimal(12,9),
				@longitude decimal (13,9)

		declare xCrsr CURSOR FOR
			select id,CityId,ProvinceStateId,CountryId,Latitude,Longitude from INSERTED where ((CityId is not null) OR (Latitude is not null AND Longitude is not null))

		OPEN xCrsr

		FETCH NEXT FROM xCrsr into @kennelId,@cityId,@regionId,@countryId,@latitude,@longitude

		WHILE @@Fetch_status = 0
		BEGIN
			IF (@latitude is not null and @longitude is not null)
				BEGIN
					UPDATE HC.Kennel SET KennelGeolocation = geography::Point(@latitude,@longitude,4326) WHERE id = @kennelId
				END
			ELSE
				IF (@cityId is not null)
					BEGIN
						UPDATE HC.Kennel SET KennelGeolocation = city.CityGeolocation FROM HC.Kennel k,
						HC.City city where city.id = @cityId and k.id = @kennelId
					END
				ELSE
					UPDATE HC.Kennel SET KennelGeolocation = null WHERE id = @kennelId

			-- we want to force city,region and country to replicate after any changes to Kennels
			-- to ensure that the records are replicated to mobile devices
			SELECT @oldCityId = CityId, @oldRegionId = ProvinceStateId, @oldCountryId = CountryId FROM DELETED WHERE id = @kennelId
			
			IF (@oldCityId IS NULL OR @cityId != @oldCityId) UPDATE HC.City SET updatedAt = getdate() where id = @cityId
			IF (@oldRegionId IS NULL OR @regionId != @oldRegionId) UPDATE HC.Region SET updatedAt = getdate() where id = @regionId
			IF (@oldCountryId IS NULL OR @countryId != @oldCountryId) UPDATE HC.Country SET updatedAt = getdate() where id = @countryId

			FETCH NEXT FROM xCrsr into @kennelId,@cityId,@regionId,@countryId,@latitude,@longitude
		END

		CLOSE xCrsr
		DEALLOCATE xCrsr
	END

END
GO

-- Trigger [HC].[trgUpdateModifiedOnDateForKennels]

CREATE   TRIGGER [HC].[trgUpdateModifiedOnDateForKennels]
   ON  HC.Kennel
   AFTER INSERT, UPDATE
AS 
BEGIN

	SET NOCOUNT ON;

	IF ((NOT UPDATE(updatedAt)) AND (NOT UPDATE(IntegrationLastExecuted)) AND (NOT UPDATE(IntegrationLastShameEmailSent)) AND (NOT UPDATE(RunsPageCheckedAt)))
	BEGIN
		UPDATE tbl Set updatedAt = dateadd(MICROSECOND,tbl.updatedAtBias,SYSDATETIME()) 
		FROM HC.Kennel tbl
		INNER JOIN INSERTED ins on tbl.id = ins.id
	END

	IF UPDATE(updatedAt)
	BEGIN
		UPDATE tbl Set updatedAt = dateadd(MICROSECOND,tbl.updatedAtBias,CAST(ins.updatedAt as datetime2)) 
		FROM HC.Kennel tbl
		INNER JOIN INSERTED ins on tbl.id = ins.id
	END

	---- if the run attendence is changed at the Kennel level
	---- make sure we update all Events for the Kennel where
	---- the CanEditRunAttendence is null so that they are
	---- propagated to the mobile devices
	--IF UPDATE(CanEditRunAttendence)
	--BEGIN
	--	UPDATE HC.Event Set updatedAt = GETDATE() FROM HC.Event 
	--		WHERE KennelId in (SELECT id from INSERTED) 
	--		AND CanEditRunAttendence is null
	--	SET NOCOUNT ON
	--END

END
GO
